-- Patient Healthcare MySQL Ready Script
-- Creates the database, tables, indexes, foreign keys, loads all 40,000 records, and creates KPI views.
-- Generated from the supplied Excel workbook. No manual CSV import is required.

DROP DATABASE IF EXISTS `patient_healthcare`;
CREATE DATABASE `patient_healthcare` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE `patients` (
  `patient_id` INT NOT NULL PRIMARY KEY,
  `gender` VARCHAR(20) NOT NULL,
  `date_of_birth` DATE NOT NULL,
  `age` TINYINT UNSIGNED NOT NULL,
  `phone_number` VARCHAR(50) NOT NULL,
  `address` TEXT NOT NULL,
  `blood_type` VARCHAR(5) NOT NULL,
  `emergency_contact` VARCHAR(50) NOT NULL,
  `insurance_provider` VARCHAR(150) NOT NULL,
  `state` VARCHAR(50) NOT NULL,
  `city` VARCHAR(80) NOT NULL,
  `country` VARCHAR(50) NOT NULL,
  `policy_number` VARCHAR(30) NOT NULL,
  `medical_history` VARCHAR(100) NULL,
  `race` VARCHAR(30) NOT NULL,
  `ethnicity` VARCHAR(30) NOT NULL,
  `marital_status` VARCHAR(30) NOT NULL,
  `first_name` VARCHAR(80) NOT NULL,
  `last_name` VARCHAR(80) NOT NULL,
  `emergency_contact_secondary` VARCHAR(50) NOT NULL,
  `chronic_conditions` VARCHAR(50) NULL,
  `allergies` VARCHAR(50) NULL,
  `contact_number` VARCHAR(50) NOT NULL

) ENGINE=InnoDB;
CREATE INDEX `idx_patients_date_of_birth` ON `patients` (`date_of_birth`);
CREATE INDEX `idx_patients_gender` ON `patients` (`gender`);
CREATE INDEX `idx_patients_state` ON `patients` (`state`);
CREATE INDEX `idx_patients_city` ON `patients` (`city`);

CREATE TABLE `doctors` (
  `doctor_id` INT NOT NULL PRIMARY KEY,
  `doctor_name` VARCHAR(120) NOT NULL,
  `specialty` VARCHAR(80) NOT NULL,
  `phone_number` VARCHAR(50) NOT NULL,
  `years_of_experience` INT NOT NULL,
  `hospital_affiliation` VARCHAR(150) NOT NULL,
  `hospital_clinic` VARCHAR(150) NOT NULL,
  `email` VARCHAR(200) NOT NULL

) ENGINE=InnoDB;
CREATE INDEX `idx_doctors_specialty` ON `doctors` (`specialty`);

CREATE TABLE `visits` (
  `visit_id` INT NOT NULL PRIMARY KEY,
  `patient_id` INT NOT NULL,
  `doctor_id` INT NOT NULL,
  `visit_date` DATE NOT NULL,
  `diagnosis` VARCHAR(100) NOT NULL,
  `follow_up_required` VARCHAR(10) NOT NULL,
  `visit_type` VARCHAR(50) NOT NULL,
  `visit_status` VARCHAR(30) NOT NULL,
  `diagnosis_code` VARCHAR(30) NOT NULL,
  `reason_for_visit` VARCHAR(100) NOT NULL,
  `prescribed_medications` VARCHAR(100) NULL
,
  CONSTRAINT `fk_visits_patient` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`patient_id`)
,
  CONSTRAINT `fk_visits_doctor` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`doctor_id`)

) ENGINE=InnoDB;
CREATE INDEX `idx_visits_patient_id` ON `visits` (`patient_id`);
CREATE INDEX `idx_visits_doctor_id` ON `visits` (`doctor_id`);
CREATE INDEX `idx_visits_visit_date` ON `visits` (`visit_date`);
CREATE INDEX `idx_visits_diagnosis` ON `visits` (`diagnosis`);
CREATE INDEX `idx_visits_follow_up_required` ON `visits` (`follow_up_required`);
CREATE INDEX `idx_visits_visit_status` ON `visits` (`visit_status`);

CREATE TABLE `treatments` (
  `treatment_id` INT NOT NULL PRIMARY KEY,
  `visit_id` INT NOT NULL,
  `medication_prescribed` VARCHAR(100) NOT NULL,
  `dosage` VARCHAR(30) NOT NULL,
  `instructions` VARCHAR(100) NOT NULL,
  `treatment_cost` DECIMAL(10,2) NOT NULL,
  `treatment_type` VARCHAR(50) NOT NULL,
  `treatment_name` VARCHAR(100) NOT NULL,
  `status` VARCHAR(30) NOT NULL,
  `cost` DECIMAL(10,2) NOT NULL,
  `outcome` VARCHAR(30) NOT NULL,
  `treatment_description` VARCHAR(100) NOT NULL
,
  CONSTRAINT `fk_treatments_visit` FOREIGN KEY (`visit_id`) REFERENCES `visits` (`visit_id`)

) ENGINE=InnoDB;
CREATE INDEX `idx_treatments_visit_id` ON `treatments` (`visit_id`);
CREATE INDEX `idx_treatments_treatment_type` ON `treatments` (`treatment_type`);
CREATE INDEX `idx_treatments_status` ON `treatments` (`status`);

CREATE TABLE `lab_results` (
  `lab_result_id` INT NOT NULL PRIMARY KEY,
  `visit_id` INT NOT NULL,
  `test_name` VARCHAR(80) NOT NULL,
  `test_date` DATE NOT NULL,
  `units` VARCHAR(20) NOT NULL,
  `comments` VARCHAR(100) NOT NULL,
  `test_result` VARCHAR(30) NOT NULL,
  `reference_range` VARCHAR(30) NOT NULL
,
  CONSTRAINT `fk_lab_results_visit` FOREIGN KEY (`visit_id`) REFERENCES `visits` (`visit_id`)

) ENGINE=InnoDB;
CREATE INDEX `idx_lab_results_visit_id` ON `lab_results` (`visit_id`);
CREATE INDEX `idx_lab_results_test_date` ON `lab_results` (`test_date`);
CREATE INDEX `idx_lab_results_test_result` ON `lab_results` (`test_result`);

