-- Load 1,000 rows into doctors

-- Load 10,000 rows into visits

-- Load 10,000 rows into treatments

-- Load 10,000 rows into lab_results

SET FOREIGN_KEY_CHECKS = 1;


USE `patient_healthcare`;

SELECT COUNT(*) AS patient_rows FROM patients;
SELECT COUNT(*) AS doctor_rows FROM doctors;
SELECT COUNT(*) AS visit_rows FROM visits;
SELECT COUNT(*) AS treatment_rows FROM treatments;
SELECT COUNT(*) AS lab_result_rows FROM lab_results;
SELECT
    ROUND(
        SUM(treatment_cost) + SUM(cost),
        2
    ) AS total_revenue
FROM treatments;

CREATE OR REPLACE VIEW `vw_kpi_summary` AS
SELECT
    (SELECT COUNT(DISTINCT patient_id) FROM patients) AS total_patients,
    (SELECT COUNT(DISTINCT doctor_id) FROM doctors) AS total_doctors,
    (SELECT COUNT(DISTINCT visit_id) FROM visits) AS total_visits,
    (SELECT ROUND(AVG(TIMESTAMPDIFF(YEAR, date_of_birth, CURDATE())), 1) FROM patients) AS average_patient_age,
    (SELECT ROUND(SUM(CASE WHEN follow_up_required = 'Yes' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(visit_id),0), 2) FROM visits) AS follow_up_rate_pct,
    (SELECT ROUND(AVG(treatment_cost), 2) FROM treatments) AS avg_treatment_cost_per_visit,
    (SELECT COUNT(DISTINCT lab_result_id) FROM lab_results) AS total_lab_tests,
    (SELECT ROUND(SUM(CASE WHEN test_result = 'Abnormal' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(lab_result_id),0), 2) FROM lab_results) AS abnormal_lab_result_pct,
    (SELECT ROUND(COUNT(DISTINCT patient_id) * 1.0 / NULLIF(COUNT(DISTINCT doctor_id),0), 2) FROM visits) AS avg_patients_per_doctor;
SELECT * FROM `vw_kpi_summary`;

CREATE OR REPLACE VIEW `vw_top5_diagnosed_conditions` AS
SELECT diagnosis, COUNT(*) AS diagnosis_count
FROM visits
WHERE diagnosis IS NOT NULL AND TRIM(diagnosis) <> ''
GROUP BY diagnosis
ORDER BY diagnosis_count DESC, diagnosis ASC
LIMIT 5;

SELECT * FROM `vw_top5_diagnosed_conditions`;



